use biome_analyze::{
    context::RuleContext, declare_rule, ActionCategory, FixKind, Rule, RuleDiagnostic,
};
use biome_console::markup;
use biome_diagnostics::Applicability;
use biome_js_syntax::{global_identifier, AnyJsExpression, AnyJsMemberExpression, JsCallExpression};
use biome_rowan::{AstNode, BatchMutationExt};

declare_rule! {
    /// Disallow the use of `console`.
    ///
    /// In a browser environment, it’s considered a best practice to log messages during development only.
    /// If you leave debugging statements in the production code, they can inadvertently expose sensitive information or clutter the browser console with unnecessary output.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```js,expect_diagnostic
    /// console.error('hello world')
    /// ```
    ///
    pub(crate) NoConsole {
        version: "next",
        name: "noConsole",
        recommended: false,
        fix_kind: FixKind::Unsafe,
    }
}

impl Rule for NoConsole {
    type Query = Semantic<JsCallExpression>;
    type State = ();
    type Signals = Option<Self::State>;
    type Options = ();

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let call_expression = ctx.query();
        let callee = call_expression.callee().ok()?;
        let member_expression =
            AnyJsMemberExpression::cast_ref(callee.omit_parentheses().syntax())?;
        let object = member_expression.object().ok()?;
        let (reference, name) = global_identifier(&object.omit_parentheses())?;
        if name.text() != "console" {
            return None;
        }
        ctx.model().binding(&reference).is_none().then_some(())
    }

    fn diagnostic(ctx: &RuleContext<Self>, _: &Self::State) -> Option<RuleDiagnostic> {
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                ctx.query().range(),
                markup! {
                    "Don't use "<Emphasis>"console"</Emphasis>""
                },
            )
            .note(markup! {
                "Usage of "<Emphasis>"console"</Emphasis>" is disallowed."
            }),
        )
    }

    fn action(ctx: &RuleContext<Self>, _: &Self::State) -> Option<JsRuleAction> {
        let call_expression = ctx.query();
        let mut mutation = ctx.root().begin();
        mutation.remove_node(call_expression.clone());
        Some(JsRuleAction {
            category: ActionCategory::QuickFix,
            applicability: Applicability::MaybeIncorrect,
            message: markup! { "Remove "<Emphasis>"console"</Emphasis>"" }.to_owned(),
            mutation,
        })
    }
}
